from catalog.codigos import codigo_desde_nombre



def asignar_codigos(apps, schema_editor):
    """Los módulos que ya existían reciben su código a partir del nombre actual."""
    Modulo = apps.get_model("clients", "Modulo")
    usados = set()
    for modulo in Modulo.objects.order_by("pk"):
        base = codigo_desde_nombre(modulo.nombre)
        candidato, n = base, 1
        while candidato in usados:
            n += 1
            candidato = f"{base}_{n}"
        usados.add(candidato)
        Modulo.objects.filter(pk=modulo.pk).update(codigo=candidato)


